W += [
E('chowder','英 /ˈtʃaʊdə/；美 /ˈtʃaʊdər/','杂烩浓汤；海鲜杂烩汤','一碗有实在配料的浓汤，常见蛤蜊、鱼、玉米或土豆，像从一大锅里舀出来的一餐。','通常认为来自法语 chaudière 锅，接晚期拉丁 caldaria 烹煮锅；由烹煮容器的名字转称其中的食物。',CAL+[['拉丁 caldaria → 法语 chaudière 锅 → 英语 chowder','一般认为先指容器，再借指一类炖煮浓汤']],'clam chowder 是蛤蜊杂烩汤；corn chowder 是玉米浓汤。很多版本用奶，但也有以番茄为底的版本，所以不能把 chowder 定死为白色奶油海鲜汤。','clam chowder；corn chowder；a bowl of chowder。','soup 范围最广；chowder 是其中一类带较多配料的浓汤。chow 食物不是它可以随意拆出的现代词根。',('The café serves corn chowder with fresh bread.','这家咖啡馆供应玉米浓汤，配新鲜面包。'),('He ordered a bowl of clam chowder by the harbour.','他在港口边点了一碗蛤蜊杂烩汤。'),sources=['https://www.etymonline.com/word/chowder','https://en.wiktionary.org/wiki/chowder#English']),
E('coddle','英 /ˈkɒdl/；美 /ˈkɑːdl/','娇惯；过分保护；用将沸的水温和烹煮','对人常是护得太周到，连一点不便和挑战都舍不得让他面对。','早期烹调义可能联系 caudle 给病人喝的温热饮品，后者接拉丁热词族。娇惯义与烹调义之间的确切联系不确定，不应讲成已经证实的温水煮人故事。',CAL+[['法语 caudel 等 → 英语 caudle 温热饮品；可能相关 → coddle 温和烹煮','这条联系通常以可能解释，不当作完全确定'],['英语 coddle 的娇惯义','较晚见于记录；与温和烹调义的具体语义衔接仍不确定']],'coddle a child 是过分娇惯孩子；coddle someone 是保护得过头。菜谱里的 coddled eggs 则是温和加热烹制的蛋，读法相同但语境不同。','coddle a child；refuse to be coddled；coddled eggs。','care for 是照顾，coddle 往往含照顾过度的批评。pamper 常强调纵容享受；coddle 更容易带不让人受一点苦的保护感。',('The coach refused to coddle the new players.','教练不愿过分护着新队员。'),('The recipe calls for gently coddled eggs.','这份食谱用到温和加热烹制的鸡蛋。'),sources=['https://www.etymonline.com/word/coddle','https://en.wiktionary.org/wiki/coddle#English']),
E('cylinder','英 /ˈsɪlɪndə/；美 /ˈsɪləndər/','圆柱；圆筒；气瓶；发动机气缸','像一个可以侧放滚动的罐体；这个外形又给容器和机器里的圆筒空间起了名字。','经法语 cylindre 或直接从拉丁 cylindrus 借入，远源希腊 kylindros 滚筒、圆柱，接 kylindein 滚动。',CYL+[['希腊 kylindros → 拉丁 cylindrus；法语 cylindre → 英语 cylinder','借入圆柱、滚筒相关名称'],['英语几何与机械用法扩展','圆柱体 → 圆筒容器、发动机气缸等']],'几何课里最常见的 cylinder 有两个平行圆形端面。a gas cylinder 是气瓶；engine cylinders 是活塞在其中运动的气缸。实物可以是中空的，不要求一整块实心。','a gas cylinder；an engine cylinder；the volume of a cylinder。','circle 是平面圆；cylinder 是立体圆柱或筒状结构。cylindrical 才是圆柱形的形容词。',('The exercise asks for the volume of a cylinder.','这道题要求计算一个圆柱体的体积。'),('The mechanic inspected one of the engine cylinders.','机修工检查了发动机的一个气缸。'),sources=['https://www.etymonline.com/word/cylinder','https://en.wiktionary.org/wiki/cylinder#English']),
E('cylindrical','/səˈlɪndrɪkl/','圆柱形的；圆筒状的','不直接把东西叫圆柱，而是说它的外形像一根筒或柱。','现代可认出 cylindr- + -ical；历史接希腊 kylindrikos 的拉丁化词族。常分析为 cylindric + -al，但现存英语记录中 cylindrical 更早，不能据此断定后记录的词一定先产生。',CYL+[['希腊 kylindrikos 圆柱的及其拉丁化形式 → 英语 cylindrical','近代形成 -ical 形容词；与 cylindric 并存，借词先后须谨慎']],'a cylindrical container 是圆筒状容器，a cylindrical tower 是圆柱形塔。它描述形状，不保证里面是实心，也不表示物体一定能自由滚动。','a cylindrical container；a cylindrical tower；a cylindrical shape。','circular 主要说圆形或环形；cylindrical 说圆柱、圆筒这种立体形状。球形则是 spherical。',('The samples were stored in small cylindrical containers.','样品存放在小圆筒容器里。'),('A cylindrical tower rises above the entrance.','入口上方矗立着一座圆柱形塔。'),sources=['https://www.etymonline.com/word/cylindrical','https://www.oxfordlearnersdictionaries.com/definition/english/cylindrical']),
E('cardinal','英 /ˈkɑːdɪnl/；美 /ˈkɑːrdɪnl/','最重要的；基本的；基数的；枢机主教；红雀','门能开合靠铰链，一件事能不能成立也常靠某个关键点；首要义就从这个枢纽意象发展。','拉丁 cardo 铰链、枢纽 → cardinalis 主要的。形容词与教会名词分别借入；鸟名则因羽色让人想到枢机主教的红衣。',CARDADJ+[['并列借入：中世纪拉丁 cardinalis〔教会职称〕→ 英语 cardinal〔名词〕','重要教会职务的称呼，不能按英语形容词记录先后来强排'],['英语 cardinal〔教会名词〕→ cardinal〔鸟名〕','红色羽毛令人联想到红衣枢机主教']],'a cardinal rule 是根本原则；cardinal numbers 是表示数量的一、二、三，区别于表示顺序的第一、第二、第三。a cardinal 还可指天主教枢机主教或红雀，需看上下文。','a cardinal rule；a cardinal error；cardinal numbers；a Catholic cardinal。','cardinal number 回答多少，ordinal number 回答第几个。cardiac 的心脏义来自另一个希腊词根，不由 cardinal 的 card- 推出。',('The cardinal rule is to keep a clear record of every change.','最基本的原则是清楚记录每一次变更。'),('The cardinal spoke to reporters after the ceremony.','仪式结束后，这位枢机主教接受了记者采访。'),sources=['https://www.etymonline.com/word/cardinal','https://en.wiktionary.org/wiki/cardinal#English']),
E('cardinality','英 /ˌkɑːdɪˈnæləti/；美 /ˌkɑːrdəˈnæləti/','基数；集合所含元素的数量','问的不是元素排第几，而是这一集合到底有多少个元素。','cardinal 的基数义 + -ity，把数量这一性质名词化；不是从枢机主教或红雀义产生。',CARDADJ+[['英语 cardinal〔基数义〕+ -ity → cardinality','表示集合大小这一数学概念']],'有限集合 {a, b, c} 的 cardinality 是 3。对无限集合也能比较基数，但不再只是普通地数到某个有限数字；不要把相同基数理解为两个集合内容完全相同。','the cardinality of a set；finite cardinality；equal cardinality。','cardinality 比较集合大小；order 可说排列顺序。两个集合元素不同，仍然可能有相同基数。',('The set has a cardinality of three.','这个集合的基数是三。'),('The two sets have the same cardinality but contain different elements.','这两个集合的基数相同，包含的元素却不同。'),sources=['https://www.merriam-webster.com/dictionary/cardinality','https://en.wiktionary.org/wiki/cardinality#English']),
E('kern','英 /kɜːn/；美 /kɜːrn/','调整字偶间距；活字伸出字身的部分〔排字名词〕','让两个特定字形靠得合适，而不是任由字身的矩形边界决定它们隔多远。','本页排字义经法语 carne 突出的角部，通常接拉丁 cardo、cardinis 铰链。它与来自爱尔兰语的士兵义、与谷粒相关的另一个 kern 不应合成同一来源。',KERN+[['英语 kern〔活字突出处〕→ kern〔调整相邻字形间距〕','从金属活字形态扩展到现代排字操作']],'kern the letters 是调整字母间距，通常按具体字偶处理，例如 A 和 V 的斜边可以让视觉空隙需要特别调整。它既可以缩小也可以增大间距。','kern a pair of letters；kern type manually；a kerned font。','kern 是动词，kerning 是调整过程。tracking 通常对一段选中文字整体增减字距，不能与逐字偶调整完全互换。',('The designer kerned the letters in the logo by hand.','设计师手工调整了标志中字母之间的间距。'),('The application can kern selected pairs automatically.','这款应用能自动调整选定字偶的间距。'),sources=['https://www.etymonline.com/word/kern','https://www.merriam-webster.com/dictionary/kern','https://helpx.adobe.com/incopy/desktop/format-text/character-formatting/kerning-tracking.html']),
E('kerning','英 /ˈkɜːnɪŋ/；美 /ˈkɜːrnɪŋ/','字偶间距调整；字偶距','盯住一对字母之间的空白，逐对调到看起来自然、易读。','kern + -ing，排字动词的过程名词；远源通过法语角部词接铰链、突出处这一历史支线。',KERN+[['英语 kern〔排字动作〕→ kerning','调整相邻特定字形的间距；也指相应间距设置']],'poor kerning 常让两个字母挤得像另一个字，或散得像断成两个词。manual kerning 是手工调整；自动 kerning 可以利用字体预设或按字形估算。','manual kerning；optical kerning；adjust the kerning；poor kerning。','tracking 改变一段文字的整体字距，kerning 处理特定字偶；leading 是行距，属于另一方向的间隔。',('The headline looked uneven because of poor kerning.','由于字偶间距处理不佳，这个标题看起来疏密不匀。'),('She adjusted the kerning between the A and the V.','她调整了 A 与 V 之间的间距。'),sources=['https://www.merriam-webster.com/dictionary/kern','https://helpx.adobe.com/incopy/desktop/format-text/character-formatting/kerning-tracking.html','https://en.wiktionary.org/wiki/kerning#English']),
]
